diffs.patch:
@@ -1,10 +1,10 @@
-name: Verify shared HUD production lifecycle
+name: Verify final DEV15.10 candidate
 on:
   push:
-    branches: [codex/shared-ui-candidate-20260925]
+    branches: [codex/canvas-cpu-dev15-10-20260925]
     paths: ['scripts/**', '.github/integrated-candidate/**', '.github/workflows/integrated-candidate.yml']
 permissions: {contents: read, actions: read}
-concurrency: {group: shared-ui-candidate, cancel-in-progress: true}
+concurrency: {group: canvas-cpu-dev15-10, cancel-in-progress: true}
 jobs:
   build:
     runs-on: ubuntu-latest
@@ -61,15 +61,9 @@ jobs:
       - uses: actions/setup-node@v4
         with: {node-version: '22'}
       - run: npm ci --ignore-scripts && npm install --no-save --package-lock=false pngjs && npx playwright install webkit
-      - name: Shared HUD real input and lifecycle
-        env: {REVIEW_BROWSER: webkit}
-        run: node .github/integrated-candidate/shared-ui.mjs "$RUNNER_TEMP/candidate" "$RUNNER_TEMP/review"
       - name: Ordinary WebKit startup and save
-        env: {EXPECTED_VERSION: 1.0.0-dev.15.9, CANDIDATE_SOURCE: '${{ github.sha }}'}
+        env: {EXPECTED_VERSION: 1.0.0-dev.15.10, CANDIDATE_SOURCE: '${{ github.sha }}'}
         run: node .github/integrated-candidate/startup.mjs "$RUNNER_TEMP/candidate" "$RUNNER_TEMP/startup"
       - uses: actions/upload-artifact@v4
         if: always()
         with: {name: integrated-startup, path: '${{ runner.temp }}/startup', retention-days: 90}
-      - uses: actions/upload-artifact@v4
-        if: always()
-        with: {name: integrated-webkit, path: '${{ runner.temp }}/review', retention-days: 90}

@@ -140,7 +140,7 @@ func run(main_node: Node) -> void :

 func _verify_build_contract() -> Dictionary:
 	var dev_feature: = OS.has_feature("ever_deeper_dev")
-	var expected_version: = "1.0.0-dev.15.9" if dev_feature else "1.0.0"
+	var expected_version: = "1.0.0-dev.15.10" if dev_feature else "1.0.0"
 	var expected_flavor: = "dev" if dev_feature else "production"
 	var actual_version: = String(PremiumMenuScript.release_version())
 	var developer_menu: Variant = _main.get("developer_menu")
